SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(6*10^9);tt:=Cputime();AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");load "work/deg10/continuation_20261031a/C56/inputs/portable_forward.m";load "work/deg10/continuation_20261031a/C56/inputs/pair_af_place_linear.m";
root:="work/deg10/continuation_20261031a/C56/";a:=eval Read(root cat "target28_proven_picard.m");k:=GF(3);PK:=PolynomialRing(k);B<t>:=FunctionField(k);R<Y>:=PolynomialRing(B);
function Rat(v)return B!(PK!v[1])/B!(PK!v[2]);end function;
F<y>:=FunctionField(R![Rat(v):v in a[1]]);assert Genus(F)eq 10;
function FF(v)return F![Rat(z):z in v];end function;
OF:=MaximalOrderFinite(F);OI:=MaximalOrderInfinite(F);
function Prime(v)O:=v[2]eq 1 select OF else OI;I:=ideal<O|[FF(z):z in v[3]]>;p:=Place(I);assert Degree(p)eq v[1];return p;end function;
fb:=[Prime([*a[3][i],a[2][i],a[4][i]*]):i in[1..#a[3]]];A:=Divisor(Prime(a[12]));Z:=FreeAbelianGroup(#a[6][1]);G,q:=quo<Z|[Z!v:v in a[6]]>;fc:=[q(Z!v):v in a[5]];H:=sub<G|[q(Z!v):v in a[13]]>;GG,pi:=quo<G|H>;coords:=[FF(v):v in a[7]];ph,witness:=C240PortableDirectRR(F,fb,fc,G,A,root cat "fourmap_native_class.log");
allowed:=AssociativeArray();for d in[0..5]do allowed[d]:={GG|};end for;allowed[0]:={GG!0};for i in[1..#a[9]]do w:=a[9][i];for d in[w..5]do allowed[d]join:={z+pi(q(Z!a[10][i])):z in allowed[d-w]};end for;end for;
print "D31A_C56_FOURMAP_GROUP_READY",Invariants(G),Invariants(H),[#allowed[d]:d in[0..5]],Cputime(tt);
src:=eval Read(root cat "source56_p3.m");fields:=AssociativeArray();for row in src[1]do fields[row[1]]:=ext<k|PK!row[2]>;end for;
function Ky(v,d)seq:=[];for j in[1..d]do Append(~seq,&cat[[Integers()!a:a in Eltseq(z,k)]:z in v]);v:=[z^3:z in v];end for;return Sort(seq)[1];end function;
extra:={};for i in[1..6]do d,ky:=Explode(src[3][i]);assert d eq 5;K:=fields[d];b:=Evaluate(PK!ky[1..d],K.1);c:=Evaluate(PK!ky[d+1..2*d],K.1);E:=EllipticCurve([K|1-c,-b,-b,0,0]);P:=E![0,0];for u in[u:u in[1..28]|GCD(u,56)eq 1]do Include(~extra,Ky(TateNormalForm_bc(E,u*P),5));end for;end for;extra:=Sort(Setseq(extra));assert #extra eq 72;
inputs:=src[3]cat[[*5,ky*]:ky in extra];records:=[* *];cache:=AssociativeArray();forward:=[* *];
for si in[1..#inputs]do d,ky:=Explode(inputs[si]);K:=fields[d];b:=Evaluate(PK!ky[1..d],K.1);c:=Evaluate(PK!ky[d+1..2*d],K.1);E:=EllipticCurve([K|1-c,-b,-b,0,0]);P:=E![0,0];assert 56*P eq E!0 and 28*P ne E!0 and 8*P ne E!0;T:=28*P;RK<X>:=PolynomialRing(K);EE,iso:=IsogenyFromKernel(E,X-T[1]);Q:=iso(P);dual:=DualIsogeny(iso);assert 28*Q eq EE!0 and 14*Q ne EE!0 and 4*Q ne EE!0 and dual(Q)eq 2*P;roots:=Roots(DivisionPolynomial(EE,2));assert #roots eq 3;ai:=aInvariants(EE);ts:=[EE![r[1],-(ai[1]*r[1]+ai[3])/2]:r in roots];ds:=[S:S in ts|dual(S)eq E!0];assert #ds eq 1;P2:=ds[1];assert P2 ne 14*Q;cls:=[* *];obs:=[* *];
 for v in[1..4]do if v le 2 then ET:=EE;QT:=v eq 1 select Q else P2+Q;else S:=v eq 3 select P2 else P2+14*Q;ET,ff:=IsogenyFromKernel(EE,RK.1-S[1]);QT:=ff(Q);end if;assert 28*QT eq ET!0 and 14*QT ne ET!0 and 4*QT ne ET!0;xy:=TateNormalForm_xy(ET,QT);ck:=[d]cat Ky(xy,d);
  if IsDefined(cache,ck)then idx:=cache[ck];cl:=q(Z!forward[idx][2]);e:=forward[idx][3];else pt:=C48PairAFPlaceLinear(coords,xy);e:=Degree(pt);assert d mod e eq 0;cl:=(d div e)*ph(Divisor(pt)-e*A);Append(~forward,[*ck,Eltseq(cl),e*]);idx:=#forward;cache[ck]:=idx;end if;Append(~cls,Eltseq(cl));Append(~obs,[v,idx,e,d div e]);
 end for;Append(~records,[*si,d,ky,cls,obs*]);if si mod 50 eq 0 then print "D31A_C56_FOURMAP_POINT_PROGRESS",si,#inputs,#forward,Cputime(tt);end if;
end for;
tests:=[* *];left:=[* *];for si in[1..#src[3]]do d:=records[si][2];flags:=[-pi(q(Z!cl))in allowed[10-d]:cl in records[si][4]];Append(~tests,[*#tests+1,[si],10-d,flags*]);if &and flags then Append(~left,tests[#tests]);end if;end for;
for fi in[1..6]do for sj in[1..72]do si:=#src[3]+sj;flags:=[-pi(q(Z!records[fi][4][v])+q(Z!records[si][4][v]))in allowed[0]:v in[1..4]];Append(~tests,[*#tests+1,[fi,si],0,flags*]);if &and flags then Append(~left,tests[#tests]);end if;end for;end for;
out:=[*src[1],records,tests,left,forward,[Eltseq(v):v in Rows(RelationMatrix(G))],[Eltseq(v):v in a[13]]*];Write(root cat "fourmap_filter.m",Sprint(out):Overwrite:=true);fprintf witness,"]\n";Flush(witness);print "D31A_C56_FOURMAP_FILTER_COMPLETE",#records,#tests,#left,[[records[v[2][1]][2],#v[2],v[3]]:v in left],Cputime(tt);quit;
